INSERT INTO tb_course(course_id,course_nm,edu_type,inst_nm,host_dept,host_dept_sub,edu_goal,edu_content,edu_days,edu_hours,edu_method,edu_place,edu_level,course_link,fw_kb1,fw_kb2,fw_kb3,is_new,is_required,is_recommend,is_published,plan_year,course_group) VALUES ('T002001044','원전 격납구조 시공 및 가동중검사 기술강좌','국내위탁','한국재료연구원','위탁교육','한울본부','격납구조는 기술기준(KEPIC, ASME)과 규제요건 등을 준수하기 위해 시공 및 가동중검사가 이루어지며, 원자력기계 분야와 달리 콘크리트, 철근 및 Post-Tensioning System에 관한 요건들을 다루고 있다. 따라서 격납구조 시공 및 가동중검사에 종사하는 토목 및 건축 기술자들을 위한 맞춤 교육으로 기술기준 요건과 기술적 배경을 설명하고, 품목 및 공정별로 기술기준 요건 준수를 위한 사례 및 이행문서로써 수강생들의 기술능력 배양을 목적으로 한다. 또한 격납구조 가동중검사의 요건 이해는 시공의 품질향상을, 시공의 요건 이해는 가동중검사의 기술적 향상을 기대할 수 있다.','○ SNA 일반요건
